theorem t2 (φ : G →* H) (S T : Subgroup G) (hST : S ≤ T) : map φ S ≤ map φ T  := by
  intro x [y, hy, rfl];
  use y, hST hyFormatting this theorem is about showing that if S is a subgroup of T, then the image of S under the homomorphism φ is a subgroup of the image of T under φ. This is a fundamental property in group theory that arises from the structure-preserving nature of group homomorphisms with respect to subgroup containment.

theorem aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K   := by
  rw [← H.index_eq_card, H.index_mul_card, h', mul_comm] at ⊢;

theorem aux_card_eq [Finite G] (h' : Nat.card G = Nat.card H * Nat.card K) :
    Nat.card (G ⧸ H) = Nat.card K  := by
  rw [← H.index_eq_card, H.index_mul_card, h', mul_comm] at ⊢ ⊢;
  exact Nat.eq_of_mul_eq_mul_right Nat.card_pos this.;

theorem iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H   := by
  exact MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K);
  rw [Nat.bijective_iff_injective_and_card];
  constructor;
  simp [h];
  exact aux_card_eq h'
